&lt;ul&gt;
&lt;li&gt;&lt;span class=&quot;TextRun SCXW37208457 BCX0&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW37208457 BCX0&quot;&gt;Own and deliver feature-level outcomes over quarters, executing within established initiatives.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;LineBreakBlob BlobObject DragDrop SCXW37208457 BCX0&quot;&gt;&lt;span class=&quot;SCXW37208457 BCX0&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;br class=&quot;SCXW37208457 BCX0&quot;&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot;TextRun SCXW37208457 BCX0&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW37208457 BCX0&quot;&gt;Contribute to strategies and propose solutions that address customer problems.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot;TextRun SCXW37208457 BCX0&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW37208457 BCX0&quot;&gt;Support defining success criteria for features; gather insights through analytics, research, and competitive analysis.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot;TextRun SCXW37208457 BCX0&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW37208457 BCX0&quot;&gt;Participate&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW37208457 BCX0&quot;&gt;&amp;nbsp;in shaping activities (e.g., spikes, usability testing, A/B tests) to de-risk features and refine solutions that enhance app capabilities.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
