&lt;li&gt;&lt;span class=&quot;TextRun SCXW37208457 BCX0&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW37208457 BCX0&quot;&gt;Coordinate cross-team dependencies; communicate progress, blockers, and impacts to stakeholders and senior product managers.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot;TextRun SCXW37208457 BCX0&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW37208457 BCX0&quot;&gt;Support collaborative workshops (ideation, unpacking, requirements gathering) and help ensure clear action plans for app improvement initiatives.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
